script.source:
if (ctx.damageType !== "Resolve" || ctx.damageValue <= 0) return false;
if (H.resource.focusCount(actor) < 1) return false;
if (
  !(await H.ask.confirm({
    title: "Make It Count",
    bodyHtml:
      "<div>Spend <strong>Focus</strong> to inflict <strong>1 Wound</strong> on the Entity (Make It Count)?</div>",
    yesLabel: "Spend Focus",
    noLabel: "Skip",
  }))
)
  return false;
await H.effects.apply(
  [
    { type: "adjustFocus", amount: -1 },
    { type: "damageEntity", wounds: 1, label: "Make It Count" },
  ],
  ctx,
);
